import { prisma } from "@/lib/prisma";
import Link from "next/link";
import {
  Radio,
  ShieldCheck,
  CheckCircle2,
  AlertTriangle,
  FileCode2,
  Clock,
  ExternalLink,
  Activity,
  ArrowDownLeft,
} from "lucide-react";

export const dynamic = "force-dynamic";

export default async function WebhooksPage() {
  // Query recent platform transactions (generated by webhooks)
  const transactions = await prisma.platformTransaction.findMany({
    take: 25,
    orderBy: { createdAt: "desc" },
  });

  // Query webhook-related audit logs
  const webhookAuditLogs = await prisma.auditLog.findMany({
    where: {
      OR: [
        { actorId: "manual_payment_verification" },
        { action: { contains: "subscription" } },
        { action: { contains: "payment" } },
      ],
    },
    take: 25,
    orderBy: { createdAt: "desc" },
  });

  // Query recent wallet transactions (student tuition split settlements)
  const walletTransactions = await prisma.walletTransaction.findMany({
    take: 25,
    orderBy: { createdAt: "desc" },
    include: {
      wallet: {
        include: {
          tenant: true,
        },
      },
    },
  });

  // Synthesize events feed
  const combinedEvents = [
    ...transactions.map((tx) => ({
      id: `tx-${tx.id}`,
      event: tx.type === "subscription" ? "subscription.renew" : "charge.success",
      reference: tx.reference,
      status: "PROCESSED",
      channel: "Bank Transfer Verification",
      amountNgn: Number(tx.amount),
      timestamp: tx.createdAt,
      details: {
        transactionId: tx.id,
        tenantId: tx.tenantId,
        type: tx.type,
      },
    })),
    ...webhookAuditLogs.map((log) => ({
      id: `log-${log.id}`,
      event: log.action.replace("_", "."),
      reference: (log.metadata as any)?.reference || `ref_${log.id.slice(0, 8)}`,
      status: log.action.includes("failed") ? "FAILED" : "PROCESSED",
      channel: "Manual SaaS Lifecycle",
      amountNgn: (log.metadata as any)?.amountNgn || null,
      timestamp: log.createdAt,
      details: log.metadata,
    })),
    ...walletTransactions.map((wt) => ({
      id: `wt-${wt.id}`,
      event: "charge.success",
      reference: wt.reference,
      status: "PROCESSED",
      channel: "Tuition Settlement",
      amountNgn: Number(wt.amount),
      timestamp: wt.createdAt,
      details: {
        schoolName: wt.wallet?.tenant?.schoolName,
        subdomain: wt.wallet?.tenant?.subdomain,
        category: wt.category,
        description: wt.description,
      },
    })),
  ].sort((a, b) => b.timestamp.getTime() - a.timestamp.getTime()).slice(0, 30);

  const formatNgn = (amt: number | null) => {
    if (amt === null || amt === undefined) return "-";
    return new Intl.NumberFormat("en-NG", {
      style: "currency",
      currency: "NGN",
      maximumFractionDigits: 0,
    }).format(amt);
  };

  return (
    <div className="space-y-8 animate-in fade-in duration-200">
      {/* Header */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pb-2 border-b border-slate-200 dark:border-zinc-800">
        <div>
          <div className="flex items-center gap-2">
            <span className="px-2.5 py-0.5 rounded-full text-[11px] font-bold uppercase tracking-wider bg-rose-100 text-rose-800 dark:bg-rose-900/40 dark:text-rose-300 border border-rose-200 dark:border-rose-800">
              Module 3
            </span>
            <span className="text-xs font-medium text-slate-500 dark:text-zinc-400">
              Transaction Event Ingestion
            </span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-extrabold tracking-tight text-slate-900 dark:text-white mt-1">
            Platform Event Ingestion &amp; Audit Stream
          </h1>
          <p className="text-xs sm:text-sm text-slate-500 dark:text-zinc-400 mt-0.5">
            Real-time delivery verification, audit logs, and transaction event stream
          </p>
        </div>

        <div className="flex items-center gap-2">
          <span className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-emerald-50 dark:bg-emerald-950/40 border border-emerald-200 dark:border-emerald-800 text-emerald-700 dark:text-emerald-300 text-xs font-semibold">
            <span className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></span>
            Audit Engine Active
          </span>
        </div>
      </div>

      {/* Endpoint Telemetry Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="p-4 rounded-xl border border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xs space-y-1.5">
          <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">Verification Pipeline</span>
          <div className="font-mono text-xs font-semibold text-indigo-600 dark:text-indigo-400 truncate">
            /api/admin/verify-subscription
          </div>
          <div className="flex items-center gap-1.5 text-[11px] text-slate-500 dark:text-zinc-400">
            <ShieldCheck className="w-3.5 h-3.5 text-emerald-500" />
            Admin Authorized Verification Enforced
          </div>
        </div>

        <div className="p-4 rounded-xl border border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xs space-y-1.5">
          <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">Events Supported</span>
          <div className="text-xs font-bold text-slate-800 dark:text-zinc-200">
            bank.transfer • proof.verified • subscription.manual
          </div>
          <div className="text-[11px] text-slate-500 dark:text-zinc-400">
            0% fee manual bank transfer &amp; offline verification
          </div>
        </div>

        <div className="p-4 rounded-xl border border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xs space-y-1.5">
          <span className="text-[11px] font-bold text-slate-400 uppercase tracking-wider">Processed Ingests</span>
          <div className="text-xl font-black text-slate-900 dark:text-white">
            {combinedEvents.length} Events Captured
          </div>
          <div className="text-[11px] text-emerald-600 dark:text-emerald-400 font-medium">
            100% Delivery Success Rate
          </div>
        </div>
      </div>

      {/* Events Log Stream */}
      <div className="rounded-2xl border border-slate-200 dark:border-zinc-800 bg-white dark:bg-zinc-900 shadow-xs overflow-hidden">
        <div className="p-4 sm:p-5 border-b border-slate-100 dark:border-zinc-800 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Activity className="w-4 h-4 text-indigo-500" />
            <h3 className="font-bold text-sm text-slate-900 dark:text-white">
              Incoming Payload Delivery Feed
            </h3>
          </div>
          <span className="text-xs text-slate-400">Most recent 30 events</span>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left text-xs whitespace-nowrap">
            <thead>
              <tr className="bg-slate-50/70 dark:bg-zinc-950/50 border-b border-slate-200 dark:border-zinc-800 text-slate-500 dark:text-zinc-400 font-bold uppercase tracking-wider text-[10px]">
                <th className="py-3 px-4">Event Type</th>
                <th className="py-3 px-4">Channel</th>
                <th className="py-3 px-4">Reference</th>
                <th className="py-3 px-4">Amount</th>
                <th className="py-3 px-4 text-center">Status</th>
                <th className="py-3 px-4 text-right">Timestamp</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 dark:divide-zinc-800/60">
              {combinedEvents.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-12 text-center text-slate-400 dark:text-zinc-500 italic">
                    <Radio className="w-8 h-8 mx-auto mb-2 text-slate-300 dark:text-zinc-700" />
                    No webhook events recorded yet. Payment verification calls will stream in live.
                  </td>
                </tr>
              ) : (
                combinedEvents.map((evt) => (
                  <tr key={evt.id} className="hover:bg-slate-50/50 dark:hover:bg-zinc-800/30 transition">
                    <td className="py-3.5 px-4">
                      <span className="font-mono font-bold text-indigo-600 dark:text-indigo-400">
                        {evt.event}
                      </span>
                    </td>
                    <td className="py-3.5 px-4 text-slate-600 dark:text-zinc-400">
                      {evt.channel}
                    </td>
                    <td className="py-3.5 px-4 font-mono text-slate-700 dark:text-zinc-300">
                      {evt.reference}
                    </td>
                    <td className="py-3.5 px-4 font-bold text-slate-900 dark:text-white">
                      {formatNgn(evt.amountNgn)}
                    </td>
                    <td className="py-3.5 px-4 text-center">
                      <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-bold ${
                        evt.status === "PROCESSED"
                          ? "bg-emerald-100 text-emerald-800 dark:bg-emerald-950/60 dark:text-emerald-300"
                          : "bg-rose-100 text-rose-800 dark:bg-rose-950/60 dark:text-rose-300"
                      }`}>
                        {evt.status === "PROCESSED" ? (
                          <><CheckCircle2 className="w-3 h-3" /> 200 OK</>
                        ) : (
                          <><AlertTriangle className="w-3 h-3" /> FAILED</>
                        )}
                      </span>
                    </td>
                    <td className="py-3.5 px-4 text-right text-slate-400 font-mono">
                      {new Date(evt.timestamp).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" })}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}
